package io.miragon.bpmn.adapter.outbound.codegen.builder.jvm

import io.miragon.bpmn.adapter.outbound.codegen.SourceCode
import io.miragon.bpmn.adapter.outbound.codegen.rendering.TemplateRenderer

/**
 * A generated Kotlin or Java file, whose imports are only known once its body is rendered. The body's template reads
 * every type through [types]; [wrapperTemplate] then puts the header, the package and exactly those imports around it:
 * ```
 * // Generated by bpmn-to-code
 * package de.emaarco.example;
 *
 * import io.miragon.bpmn.runtime.ProcessId;
 *
 * public final class BikeLeasingProcessApi { … }
 * ```
 */
internal class ImportingSourceFile(
    private val wrapperTemplate: String,
    private val packageName: String,
    val types: TypeReferences,
) {

    fun render(templateName: String, model: Any): SourceCode {
        val body = TemplateRenderer.render(templateName = templateName, model = model)
        val wrapped = TemplateRenderer.render(
            templateName = wrapperTemplate,
            model = Wrapper(packageName = packageName, imports = types.imports, body = body),
        )
        return SourceCode(wrapped)
    }

    data class Wrapper(val packageName: String, val imports: List<String>, val body: String)
}
